import React from "react";

function Home() {

  const products = [
    {
      _id: 1,
      name: "Nike Shoes",
      price: 2999,
      image: "https://images.unsplash.com/photo-1542291026-7eec264c27ff"
    },
    {
      _id: 2,
      name: "T-Shirt",
      price: 999,
      image: "https://images.unsplash.com/photo-1521572163474-6864f9cf17ab"
    },
    {
      _id: 3,
      name: "Headphones",
      price: 1999,
      image: "https://images.unsplash.com/photo-1505740420928-5e560c06d30e"
    }
  ];

  return (
    <div style={{
      backgroundColor: "#f5f5f5",
      minHeight: "100vh",
      padding: "30px"
    }}>

      <h1 style={{
        textAlign: "center",
        marginBottom: "40px",
        color: "#222"
      }}>
        🛒 ShopEasy
      </h1>

      <div style={{
        display: "flex",
        gap: "30px",
        justifyContent: "center",
        flexWrap: "wrap"
      }}>

        {products.map((p) => (
          <div
            key={p._id}
            style={{
              background: "white",
              width: "250px",
              borderRadius: "12px",
              overflow: "hidden",
              boxShadow: "0 4px 10px rgba(0,0,0,0.2)",
              transition: "0.3s"
            }}
          >

            <img
              src={p.image}
              alt={p.name}
              style={{
                width: "100%",
                height: "220px",
                objectFit: "cover"
              }}
            />

            <div style={{ padding: "15px" }}>

              <h2 style={{
                fontSize: "22px",
                marginBottom: "10px"
              }}>
                {p.name}
              </h2>

              <p style={{
                fontSize: "18px",
                color: "green",
                fontWeight: "bold"
              }}>
                ₹{p.price}
              </p>

              <button style={{
                marginTop: "15px",
                width: "100%",
                padding: "10px",
                backgroundColor: "#222",
                color: "white",
                border: "none",
                borderRadius: "8px",
                cursor: "pointer",
                fontSize: "16px"
              }}>
                Add to Cart
              </button>

            </div>

          </div>
        ))}

      </div>

    </div>
  );
}

export default Home;
